"""Complete 20 original delirium and neuropsychiatry questions."""
from create_psych_delirium import rows,q,DL,DM,ref
from qbank_authoring import finalize
FN=ref('Functional neurological disorder: positive diagnosis and management','https://doi.org/10.1136/bmj.o64')
SO=ref('American Psychiatric Association: somatic symptom and related disorders','https://www.psychiatry.org/patients-families/somatic-symptom-disorder/what-is-somatic-symptom-disorder/')

q('Progressive cognitive decline is accompanied by recurrent well-formed visual hallucinations, spontaneous parkinsonism and marked fluctuations. Which diagnosis is most likely?', 'Dementia with Lewy bodies',[
 ('Typical amnestic Alzheimer disease as the only explanation','The early hallucination, fluctuation and parkinsonian cluster favors Lewy body disease.'),('Behavioral-variant frontotemporal dementia','Early disinhibition and personality/executive changes are more characteristic.'),('A single brief delirium episode as a complete explanation for the progressive course','Superimposed delirium is possible, but the chronic syndrome requires a broader diagnosis.')],
 'Neuropsychiatric features can identify a dementia phenotype','**Fluctuation, visual hallucinations and parkinsonism are important Lewy body clues.**',['REM-sleep behavior disorder can add support.','Assess for superimposed delirium and medication effects.'],'**Use specialist assessment and cautious symptom treatment.**',['Antipsychotic sensitivity is a major safety concern.','Cholinesterase inhibitors may have a role according to the clinical plan.'],[['Lewy body','Hallucinations/fluctuation/parkinsonism'],['Alzheimer','Often early amnestic pattern'],['FTD','Behavior/language-predominant patterns']],[DM],style='clinical_scenario')

q('A 58-year-old develops progressive disinhibition, loss of empathy, compulsive routines and altered eating behavior before major memory impairment. Which syndrome is most likely?', 'Behavioral-variant frontotemporal dementia',[
 ('Typical amnestic Alzheimer disease','The early behavioral/social-cognitive syndrome is less typical.'),('Uncomplicated major depression','Progressive disinhibition and loss of empathy differ from the usual depressive pattern.'),('A lifelong personality disorder established by the new behavior','A new progressive change from prior baseline requires a neurocognitive assessment.')],
 'A new personality change can be neurological','**FTD can present with behavior and executive dysfunction before prominent episodic-memory loss.**',['Age and progression support the differential but are not diagnostic alone.','Language, motor-neuron and movement features may coexist.'],'**Obtain collateral history and specialist cognitive/neurological evaluation.**',['Assess capacity and financial/social safety.','Support caregivers and avoid interpreting symptoms as deliberate misconduct.'],[['Early domain','Behavior/social cognition'],['Course','Progressive'],['Assessment','Collateral and neurological/cognitive workup']],[DM],style='clinical_scenario')

q('What distinguishes mild cognitive impairment from dementia at the syndrome level?', 'Cognitive decline is present but does not substantially interfere with independent everyday functioning',[
 ('MCI requires that every cognitive test be normal','Objective decline may be measurable.'),('MCI guarantees there will be no progression','The course varies and follow-up is needed.'),('Dementia is diagnosed from any subjective memory complaint alone','Functional impact and objective assessment are important.')],
 'Function separates related levels of impairment','**Cognitive scores must be interpreted with real-world independence.**',['Compensatory strategies can preserve function despite deficits.','Depression, delirium, sensory problems and medication effects can influence testing.'],'**Evaluate cause and follow the trajectory.**',['Manage vascular and other modifiable contributors.','Provide advice and support proportional to the person’s needs.'],[['MCI','Decline with relative independence'],['Dementia','Decline impairs independent function'],['Follow-up','Cause and progression']],[DM])

q('A patient with possible dementia has fluctuating symptoms, recent medication changes and untreated hearing loss. Which approach is best?', 'Address reversible/confounding factors and use a comprehensive cognitive and functional assessment',[
 ('Diagnose Alzheimer disease from one low screening score','A single score can be confounded.'),('Exclude cognitive disease because hearing loss is present','Hearing loss and cognitive disease can coexist.'),('Use brain imaging alone as a complete diagnosis','History, examination, function and cognitive testing remain essential.')],
 'A score is a measurement, not an etiological diagnosis','**Sensory impairment, drugs, mood and delirium can distort cognitive performance.**',['Collateral functional history helps establish the pattern.','Investigate relevant medical causes and use imaging when indicated.'],'**Reassess after modifiable factors are addressed.**',['Use appropriate communication and validated testing conditions.','Do not delay support while the etiological formulation is refined.'],[['Testing','Context-dependent'],['Confounders','Sensory/drug/mood/acute illness'],['Diagnosis','Integrated clinical formulation']],[DM],style='clinical_scenario')

q('A person with dementia becomes newly aggressive during personal care. Which initial assessment is most useful?', 'Look for pain, delirium, fear, communication barriers and unmet physical or environmental needs',[
 ('Escalate antipsychotics before checking for causes','Medication can add harm and miss a treatable trigger.'),('Assume all behavior is an inevitable untreatable progression','Behavior often reflects modifiable distress.'),('Use physical restraint as the default long-term solution','This can worsen distress and create injury.')],
 'Behavior can communicate an unmet need','**New distress requires a structured cause assessment.**',['Constipation, urinary retention, infection and overstimulation can contribute.','The person’s preferences and usual routines matter.'],'**Use tailored nonpharmacological measures first where safe.**',['Medication may be justified for severe distress or danger after risk review.','Review benefit frequently and avoid indefinite continuation without need.'],[['Possible triggers','Pain/illness/environment'],['First response','Assessment and tailored support'],['Drugs','Selected risk-benefit role']],[DM],style='clinical_scenario')

q('A patient has apparent hip-extension weakness that improves during contralateral resisted hip flexion, with the appropriate positive examination pattern. What does this support?', 'Functional limb weakness based on a positive inconsistency between voluntary and automatic movement',[
 ('Proof that the patient is consciously feigning','Functional symptoms are not equivalent to intentional fabrication.'),('A diagnosis based solely on normal imaging','Positive signs, not absence of lesions alone, support FND.'),('Exclusion of every coexisting neurological disease','Functional and structural disorders can coexist.')],
 'Use positive signs respectfully','**Hoover-type findings can demonstrate preserved automatic motor capacity.**',['Interpret in the context of pain, comprehension and the complete examination.','Do not rely on a single poorly performed maneuver.'],'**Explain the diagnosis and offer rehabilitation.**',['Communicate that symptoms are real and potentially treatable.','Assess other neurological disease when findings warrant it.'],[['Positive sign','Voluntary/automatic discrepancy'],['Not established','Deliberate feigning'],['Management','Explanation and rehabilitation']],[FN],style='clinical_scenario')

q('What is the most appropriate way to communicate a well-supported functional neurological disorder diagnosis?', 'Explain the positive findings, validate the symptoms and describe a treatment pathway focused on function',[
 ('Say that normal tests prove nothing is wrong','This dismisses the symptoms and does not explain the disorder.'),('Tell the patient that all symptoms must be consciously produced','Intentional production is not the defining mechanism.'),('Avoid giving any diagnosis until every conceivable test has been done','Excessive unstructured testing can delay appropriate care when a positive diagnosis is supported.')],
 'A clear explanation is part of treatment','**FND can be diagnosed from characteristic positive clinical features.**',['Psychological stress is not required as a universal diagnostic prerequisite.','Mechanisms and comorbidities vary.'],'**Offer symptom-appropriate multidisciplinary care.**',['Physiotherapy, occupational/speech therapy and psychotherapy have roles according to presentation.','Provide follow-up and reassess genuinely new findings.'],[['Explanation','Positive evidence'],['Validation','Real symptoms'],['Plan','Function-focused treatment']],[FN])

q('A patient has seizure-like episodes. Which investigation most strongly supports a functional seizure diagnosis when a typical event is captured and assessed by an experienced team?', 'Video-EEG with compatible event semiology and no corresponding epileptic ictal pattern',[
 ('A single normal routine interictal EEG as definitive proof','Interictal EEG can be normal in epilepsy.'),('An elevated anxiety score alone','Anxiety is nonspecific and can coexist with epilepsy.'),('An episode occurring in front of witnesses as proof of intentional production','Witness presence does not establish mechanism or intent.')],
 'Capture the habitual event rather than overinterpreting a normal interval','**Video and EEG must be interpreted together with the event characteristics.**',['Some epileptic events can lack an obvious scalp correlate, so expertise matters.','Functional seizures and epilepsy can coexist.'],'**Communicate the diagnosis carefully and plan appropriate treatment.**',['Avoid unnecessary antiseizure escalation when epilepsy is not the cause.','Do not abruptly stop treatment for a coexisting epilepsy disorder.'],[['Routine EEG','May be normal in epilepsy'],['Typical captured event','More informative'],['Interpretation','Expert electroclinical assessment']],[FN],style='clinical_scenario')

q('Which statement about somatic symptom disorder is correct?', 'The diagnosis concerns disproportionate symptom-related thoughts, feelings or behaviors and does not require that every symptom be medically unexplained',[
 ('A normal test result alone establishes the disorder','Normal testing does not define the psychological/behavioral criteria.'),('A proven medical illness excludes the disorder','Excessive distress and behavior can coexist with medical disease.'),('The symptoms must be intentionally fabricated','Intentional fabrication is a different construct.')],
 'Do not equate unexplained with psychiatric','**The relationship to symptoms and the resulting burden are central.**',['Symptoms are experienced as real.','Medical and psychiatric care should be coordinated.'],'**Use consistent follow-up and a shared functional plan.**',['Avoid both endless low-value testing and dismissal of new red flags.','Treat comorbid anxiety/depression and consider evidence-based psychotherapy.'],[['Core','Excessive symptom-related response'],['Medical explanation','May be present'],['Intent','Not deliberate fabrication']],[SO])

q('A patient is preoccupied with having a serious disease despite minimal physical symptoms and repeatedly checks for illness. Which diagnosis is most consistent?', 'Illness anxiety disorder',[
 ('Somatic symptom disorder as established by minimal symptoms alone','SSD more centrally involves distressing somatic symptoms with excessive responses.'),('Factitious disorder','This requires evidence of intentional falsification/induction, not simply fear.'),('Malingering','This involves intentional symptom production for external incentive, which is not described.')],
 'Fear of disease differs from fabrication of disease','**Illness anxiety can be prominent when somatic symptoms are absent or mild.**',['Assess persistence, reassurance seeking and avoidance.','Appropriate medical evaluation remains important.'],'**Offer a consistent therapeutic approach and avoid reinforcing checking cycles.**',['Use planned follow-up and psychological treatment when indicated.','Reassess new objective findings without diagnostic overshadowing.'],[['Illness anxiety','Disease preoccupation with few symptoms'],['Factitious','Intentional falsification without obvious external reward'],['Malingering','Intentional production for external incentive']],[SO],style='clinical_scenario')

if __name__=='__main__':finalize('Psychiatry',5,'Delirium and Neuropsychiatry','psych-neuropsychiatry',rows,20)
